transforms.code:
# The operation's linked assets and the assets under them, or every asset when it has no links. Transports aren't places.
if not value:
	return []
paths = value['assetPaths']
rows = []
if paths:
	for path in paths:
		rows += system.kanoa.utilities.convertDatasetToJSON(system.kanoa.asset.getAssets({'assetPath': path}))
		rows += system.kanoa.utilities.convertDatasetToJSON(system.kanoa.asset.getAssets({'assetPath': path + '\\%'}))
else:
	rows = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.asset.getAssets({'enabled': True}))
options = {}
for row in rows:
	if row['enabled'] and not row['mobile']:
		options[row['assetPath']] = row['displayPath'] or row['assetPath']
return [{'label': options[path], 'value': path} for path in sorted(options)]

crud = value['userCRUD'] if value else None
if crud is None or value['userId'] is None:
	return False
return bool(crud['isGatewayAdmin'] or crud['configureLots']['enabled'])

# Sensible starting values for the form when the operation or the selected lot changes
op, lot = value['op'], value['lot']
if not op:
	return None
name = op['name']
if not op['allowOutput'] or name in ('Scrap', 'Ship'):
	mode = 'none'
elif name in ('Transfer', 'Inspect'):
	mode = 'same'
else:
	mode = 'new'
offered = [o['value'] for o in value['assets'] or []]
asset = None
if name == 'Receive':
	asset = value['receiving'] if value['receiving'] in offered else None
elif lot and name != 'Transfer':
	asset = lot['assetPath'] if lot['assetPath'] in offered else None
okState = [s['value'] for s in value['states'] if s['label'] == 'OK']
qty = lot['qty'] if lot else 0
return {
	'assetPath': asset, 'inputQty': qty, 'outputMode': mode, 'outputQty': qty if mode == 'same' else 0,
	'itemId': None, 'itemUnitId': lot['itemUnitId'] if (lot and op['usesInput']) else None,
	'lotStateId': okState[0] if okState else None,
	'transportId': lot['assetTransportId'] if (lot and mode == 'same') else None,
}

onChange.script:
# Entering a time starts from now
if not currentValue.value and self.custom.form.tStamp is None:
	self.custom.form.tStamp = system.date.now()

transforms.code:
# The chosen operation, its asset links and the items its outputs can be
if not value:
	return None
op = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.lot.getLotOperations({'lotOperationName': value}))
if not op:
	return None
op = op[0]
opIds = [op['lotOperationId']]
assetLinks = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.lot.getLotOperationAssetLinks({'lotOperationIdList': opIds}))
itemLinks = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.lot.getLotOperationItemLinks({'lotOperationIdList': opIds}))
def linkedItems(source):
	# {itemId: itemName} for the operation's enabled links of that source: an item, or every item of a class
	links = [l for l in itemLinks if l['linkEnabled'] and l['itemSourceName'] == source]
	found = {}
	for link in links:
		if link['itemId']:
			found[link['itemId']] = link['itemName']
		elif link['itemClassId']:
			for item in system.kanoa.utilities.convertDatasetToJSON(system.kanoa.item.getItems({'itemClassId': link['itemClassId']})):
				found[item['itemId']] = item['itemName']
	return links, found
outputLinks, items = linkedItems('output')
inputLinks, inputItems = linkedItems('input')
if not outputLinks:
	for item in system.kanoa.utilities.convertDatasetToJSON(system.kanoa.item.getItems({'enabled': True})):
		items[item['itemId']] = item['itemName']
return {
	'lotOperationId': op['lotOperationId'], 'name': op['lotOperationName'],
	'usesInput': bool(op['allowInputLots']) and op['lotOperationName'] != 'Receive',
	'allowOutput': bool(op['allowOutputLots']),
	'assetPaths': [l['assetPath'] for l in assetLinks if l['linkEnabled']],
	# The items an input lot can be; None when the operation has no input links (any lot)
	'inputItemIds': sorted(inputItems.keys()) if inputLinks else None,
	'itemOptions': sorted([{'label': name, 'value': itemId} for itemId, name in items.items()], key=lambda o: o['label']),
}

# The next lot name from the chosen serialization, worked out as getNextSerialNumber does: the value + 1, zero filled, between the prefix and suffix
if value['serialId'] is None:
	return None
serial = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.serial.getSerialNumbers({'serialId': value['serialId']}), 0)
if serial['serialId'] is None:
	return None
return '%s%s%s' % (serial['prefix'] or '', str((serial['serialValue'] or 0) + 1).zfill(serial['zfill'] or 0), serial['suffix'] or '')

config.script:
# One run per click: a click queued behind a run, or one after the operation ran (its form is hidden and the
# "Add another" prompt shows), does nothing
if self.view.custom.running or (self.view.custom.lastRun is not None and not self.view.custom.editing):
	return
self.view.custom.running = True
try:
	userId = self.view.custom.security.userId
	sources = system.kanoa.utilities.convertDatasetToDict(system.kanoa.item.getItemSource({}), 'itemSourceName', 'itemSourceId')

	timeFormat = system.kanoa.date.localizeDateFormat('yyyy-MM-dd HH:mm:ss', self.session.props.locale)	# times in this script's messages, in the session's date order
	deviceTimezone = self.session.props.device.timezone.id
	def shown(d):
		# A time as the user's device shows it: system.date.format uses the gateway's timezone
		return system.date.format(system.date.addMinutes(d, -system.kanoa.date.getClientOffsetMinsFromGateway(deviceTimezone, d)), timeFormat)
	def toast(kind, message):
		system.kanoa.toast.show({'type': kind, 'message': message})

	def lotEvent(lot, qty, assetId, source, tStamp, lotStateId, lotStateReasonId=None, transportId=None, comment=None, workOrderId=None, lotEventId=None):
		"""A lot event for a lot that exists."""
		return {
			'lotEventId': lotEventId, 'lotOperationEventId': None,
			'lotId': lot['lotId'], 'lotName': lot['lotName'], 'itemId': lot['itemId'], 'itemUnitId': lot['itemUnitId'],
			'lotEventQty': qty, 'assetId': assetId, 'itemSourceId': sources[source],
			'lotStateId': lotStateId, 'lotStateReasonId': lotStateReasonId,
			'workOrderId': workOrderId, 'shiftId': None, 'tStamp': tStamp, 'comment': comment or None, 'assetTransportId': transportId,
		}

	def ms(d):
		return d.getTime() if hasattr(d, 'getTime') else d

	def timeError(tStamp, lots, editing, ownId=None):
		# Why tStamp would put a lot's events out of order, or None. When editing, the operation's own events don't count,
		# events before its original time must stay before it, and events after must stay after. When adding to the
		# operation just run (ownId), its own events don't count either: the database rounds their milliseconds, sometimes
		# up, so they can read as a moment after the operation's time
		editingId = editing['lotOperationEventId'] if editing else ownId
		original = ms(editing['originalTime']) if editing else None
		for lotId, lotName in lots.items():
			events = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.lot.getLotEvents({'lotId': lotId}))
			others = [ms(e['tStamp']) for e in events if e['tStamp'] is not None and e['lotOperationEventId'] != editingId]
			before = [t for t in others if original is None or t <= original]
			after = [t for t in others if original is not None and t > original]
			if before and ms(tStamp) < max(before):
				return 'The time is before the last earlier event of %s, at %s. Choose a later time.' % (lotName, shown(system.date.fromMillis(max(before))))
			if after and ms(tStamp) > min(after):
				return 'The time is after the next event of %s, at %s. Choose an earlier time.' % (lotName, shown(system.date.fromMillis(min(after))))
		return None

	op = self.view.custom.opInfo
	form = self.view.custom.form
	root = self.view.getChild('root')
	editing = self.view.custom.editing
	appendTo = self.view.custom.appendTo   # adding an input or output to the operation just run
	if op is None:
		toast('warning', 'Choose an operation.')
		return

	# The time: the operation's when adding to it, now when the button is clicked, or the time entered
	tStamp = appendTo['tStamp'] if appendTo else (system.date.now() if form.useNow else form.tStamp)
	if tStamp is None:
		toast('warning', 'Enter the time of the %s, or tick Use the current time.' % op['name'])
		return
	if not appendTo and not form.useNow and system.date.isAfter(tStamp, system.date.now()):
		toast('warning', "The time can't be in the future.")
		return

	# Adding to the operation just run: only the input or the output being added
	if appendTo:
		inputs, outputs = [], []
		error, data = root.inputFromForm() if appendTo['part'] == 'input' else root.outputFromForm()
		if error:
			toast('warning', error)
			return
		if appendTo['part'] == 'input':
			inputs = [data]
		else:
			outputs = [data]
	# Editing uses the lists. A new operation uses the input list plus the lot in the fields (unless it's already in the
	# list), and the output fields
	def bucket(lot):
		return (lot['lotId'], lot['assetId'], lot['lotStateId'], lot.get('lotStateReasonId'))
	inputs = inputs if appendTo else list(self.view.custom.inputs)
	if op['usesInput'] and not editing and not appendTo and (not inputs or self.view.custom.inputLot):
		error, data = root.inputFromForm()
		if error:
			toast('warning', error)
			return
		keys = [i['key'] for i in inputs]
		if data['key'] in keys:
			inputs[keys.index(data['key'])] = data
		elif bucket(data) not in [bucket(i) for i in inputs]:
			inputs.append(data)
	outputs = outputs if appendTo else list(self.view.custom.outputs)
	if op['allowOutput'] and form.outputMode != 'none' and not outputs and not editing and not appendTo:
		error, data = root.outputFromForm()
		if error:
			toast('warning', error)
			return
		outputs = [data]
	if not inputs and not outputs:
		toast('warning', 'This operation needs at least one input or output.')
		return

	# Where the operation happens: the chosen asset, or where the input lot already is
	assetPath = appendTo['assetPath'] if appendTo else (form.assetPath or (inputs[0]['assetPath'] if inputs else None))
	if not assetPath:
		toast('warning', 'Choose the asset where the %s happens.' % op['name'])
		return
	assetIds = {}
	def assetId(path):
		if not path:
			raise ValueError('No asset path')   # getAssets with no path returns every asset
		if path not in assetIds:
			assetIds[path] = system.kanoa.utilities.getFieldValue('assetId', system.kanoa.asset.getAssets({'assetPath': path}))
		return assetIds[path]
	# Plain dicts: the list's entries are read-only copies, so setting their asset wouldn't stick
	outputs = [dict(o) for o in outputs]
	for o in outputs:
		o['assetPath'] = assetPath   # every output goes where the operation happens
		if o['mode'] == 'same' and op['name'] == 'Transfer' and o['assetPath'] == o['lot']['assetPath'] and o['lotStateId'] == o['lot']['lotStateId'] and o['transportId'] == o['lot']['assetTransportId']:
			toast('warning', 'Choose a destination other than where %s is now.' % o['lotName'])
			return

	# The time has to keep every lot's events in order, or the trace graph runs backwards
	lots = dict((i['lotId'], i['lotName']) for i in inputs)
	lots.update(dict((o['lot']['lotId'], o['lot']['lotName']) for o in outputs if o['mode'] in ('same', 'existing')))
	error = timeError(tStamp, lots, editing, appendTo['lotOperationEventId'] if appendTo else None)
	if error:
		toast('warning', error)
		return

	# The order number, if one was entered
	workOrderId = None
	orderName = appendTo['orderName'] if appendTo else (form.orderName or '').strip()
	if orderName:
		workOrderId = system.kanoa.utilities.getFieldValue('workOrderId', system.kanoa.order.getProductionOrders({'workOrderName': orderName}))
		if workOrderId is None:
			toast('warning', 'There is no order %s.' % orderName)
			return

	# Inputs come off the transport the lot is on now
	# Inputs consume the bucket the lot is in, reason included: a lot's stock is per asset, lot state and lot state reason
	inputEvents = [lotEvent(i, i['inputQty'], i['assetId'], 'input', tStamp, i['lotStateId'], lotStateReasonId=i.get('lotStateReasonId'), transportId=i['assetTransportId'], workOrderId=workOrderId, lotEventId=i.get('lotEventId')) for i in inputs]
	# Serial numbers a failed run took, by serialization: a retry uses them again, so failed runs leave no gaps
	spare = dict((key, list(names)) for key, names in (self.view.custom.spareSerialNames or {}).items())
	taken = {}
	def keepSpare(used):
		# What's left for the next run: the serial numbers this run took, if it failed, then the unused ones
		names = dict((key, list(used.get(key, [])) + spare.get(key, [])) for key in set(used) | set(spare))
		self.view.custom.spareSerialNames = dict((key, n) for key, n in names.items() if n)

	outputEvents = []
	for o in outputs:
		extra = {'lotStateReasonId': o['lotStateReasonId'], 'transportId': o['transportId'], 'comment': o['comment'], 'workOrderId': workOrderId}
		if o['mode'] in ('same', 'existing'):
			outputEvents.append(lotEvent(o['lot'], o['qty'], assetId(o['assetPath']), 'output', tStamp, o['lotStateId'], lotEventId=o.get('lotEventId'), **extra))
			continue
		# A new lot: the name entered, or the next number from the serialization. executeLotOperation creates it in the
		# operation's transaction, so a failed run leaves no lot behind.
		lotName = o['newLotName']
		if not lotName:
			serialKey = str(o['serialId'])
			pool = spare.get(serialKey, [])
			while pool and not lotName:
				name = pool.pop(0)
				if len(system.kanoa.lot.getLots({'lotName': name})) == 0:   # skip one a lot has been given since
					lotName = name
			if not lotName:
				lotName, msg = system.kanoa.serial.getNextSerialNumber(o['serialId'], userId)
				if msg is not None:
					keepSpare(taken)
					toast('error', "Couldn't get a lot name from the serialization: %s" % msg)
					return
			taken.setdefault(serialKey, []).append(lotName)
		newLot = {'lotId': None, 'lotName': lotName, 'itemId': o['itemId'], 'itemUnitId': o['itemUnitId']}
		outputEvents.append(lotEvent(newLot, o['qty'], assetId(o['assetPath']), 'output', tStamp, o['lotStateId'], **extra))

	existingId = editing['lotOperationEventId'] if editing else (appendTo['lotOperationEventId'] if appendTo else None)
	operationInfo = {'lotOperationEventId': existingId, 'lotOperationId': op['lotOperationId'], 'assetId': assetId(assetPath), 'tStamp': tStamp, 'enabled': True}
	lotOperationEventId, msg = system.kanoa.lot.executeLotOperation(operationInfo, inputEvents, outputEvents, userId)
	keepSpare({} if msg is None else taken)
	if msg is None:
		# Lot events taken out of an edited operation
		for lotEventId in (self.view.custom.removedLotEventIds if editing else []):
			retVal, deleteMsg = system.kanoa.lot.deleteLotEvent(lotEventId, userId)
			if deleteMsg:
				toast('error', "Couldn't delete a removed lot event: %s" % deleteMsg)
		names = ', '.join(e['lotName'] for e in outputEvents) or ', '.join(e['lotName'] for e in inputEvents)
		where = assetPath.split('\\')[-1]
		if appendTo:
			done = '%s added to the %s at %s.' % (names, op['name'], where)
		else:
			done = '%s %s at %s: %s.' % (op['name'], 'saved' if editing else 'done', where, names)
		toast('success', done)
		wasEditing = bool(editing)
		# Offer to add another input or output to the operation just run
		if editing:
			self.view.custom.lastRun = None
		else:
			self.view.custom.lastRun = {'lotOperationEventId': lotOperationEventId, 'operation': op['name'], 'tStamp': tStamp,
				'assetPath': assetPath, 'orderName': orderName,
				'label': '%s at %s, %s' % (op['name'], where, shown(tStamp)),
				'message': done}
		# Select the operation's lot in the table once it reloads, so its trace shows
		shown = outputEvents[0] if outputEvents else (inputEvents[0] if inputEvents else None)
		if shown and shown['lotId'] is None:   # a lot the operation created
			shown = dict(shown, lotId=system.kanoa.utilities.getFieldValue('lotId', system.kanoa.lot.getLots({'lotName': shown['lotName']})))
		selectLot = {'lotId': shown['lotId'], 'assetPath': assetPath if outputEvents else inputs[0]['assetPath']} if shown else None
		self.view.custom.appendTo = None
		self.view.custom.editing = None
		self.view.custom.removedLotEventIds = []
		self.view.custom.form.useNow = True
		self.view.custom.inputs = []
		self.view.custom.outputs = []
		system.perspective.sendMessage('lotUpdate', {'selectLot': selectLot}, scope='page')
		if wasEditing:
			system.perspective.closePopup('')
	else:
		toast('error', "Couldn't run the %s: %s" % (op['name'], msg))
		system.perspective.sendMessage('lotUpdate', {}, scope='page')
finally:
	try:
		self.view.custom.running = False
	except:
		pass   # the popup closed (after saving an edit)

# Open the operation to edit, or start a new one: a Transfer of the lot selected in the lot table, if there is one
lot = self.view.params.selectedLot
if lot:
	self.view.custom.inputLot = dict(lot)
	self.view.custom.inputLotKey = '%s|%s|%s|%s' % (lot['lotId'], lot['assetId'], lot['lotStateId'], lot['lotStateReasonId'])
if self.view.params.lotOperationEventId is not None:
	self.editOperation(self.view.params.lotOperationEventId)
elif lot:
	self.view.custom.operation = 'Transfer'
